  int lid = int(gl_LocalInvocationID.x);
  int wid = int(gl_WorkGroupID.x);
  int wg_size = 256;

  if (pass == 0) { // Block-wise inclusive scan
    int val = 0;
    if (idx < n) val = data[idx];

    // Hillis-Steele inclusive scan
    temp[lid] = val;
    barrier();

    for (int stride = 1; stride < wg_size; stride <<= 1) {
      int v = 0;
      if (lid >= stride) v = temp[lid - stride];
      barrier();
      temp[lid] += v;
      barrier();
    }

    if (idx < n) data[idx] = temp[lid];
    if (lid == wg_size - 1 || idx == n - 1) {
      block_sums[wid] = temp[lid];
    }
  } else if (pass == 1) { // Scan block sums
    int val = 0;
    if (idx < (n + wg_size - 1) / wg_size) val = block_sums[idx];

    temp[lid] = val;
    barrier();

    for (int stride = 1; stride < wg_size; stride <<= 1) {
