    if (idx < (n + wg_size - 1) / wg_size) block_sums[idx] = temp[lid];
  } else if (pass == 2) { // Add block prefix sums (exclusive)
    if (wid > 0 && idx < n) {
      int block_prefix = block_sums[wid - 1];
      data[idx] += block_prefix;
    }

    // Convert to exclusive scan
