layout(local_size_x = 256) in;

layout(set = 0, binding = 0) buffer InputData { int data[]; };
layout(set = 0, binding = 1) buffer InclusiveScan { int inclusive[]; };
layout(set = 0, binding = 2) buffer BlockSums { int block_sums[]; };
layout(set = 0, binding = 3) buffer OutputData { int out_data[]; };

layout(push_constant) uniform Params {
  int n;
  int pass;
};

shared int temp[512];

void main() {
  int idx = int(gl_GlobalInvocationID.x);
  int lid = int(gl_LocalInvocationID.x);
  int wid = int(gl_WorkGroupID.x);
  int wg_size = 256;

  if (pass == 0) {
    int val = 0;
    if (idx < n) val = data[idx];
    temp[lid] = val;
    barrier();
    for (int stride = 1; stride < wg_size; stride <<= 1) {
      int v = 0;
      if (lid >= stride) v = temp[lid - stride];
      barrier();
      temp[lid] += v;
      barrier();
    }
    if (idx < n) inclusive[idx] = temp[lid];
    if (lid == wg_size - 1 || idx == n - 1) block_sums[wid] = temp[lid];
  } else if (pass == 1) {
    int count = (n + wg_size - 1) / wg_size;
    int val = 0;
    if (idx < count) val = block_sums[idx];
    temp[lid] = val;
    barrier();
    for (int stride = 1; stride < wg_size; stride <<= 1) {
      int v = 0;
      if (lid >= stride) v = temp[lid - stride];
      barrier();
      temp[lid] += v;
      barrier();
    }
    if (idx < count) block_sums[idx] = temp[lid];
  } else if (pass == 2) {
    if (idx < n) {
      int block_prefix = (wid > 0) ? block_sums[wid - 1] : 0;
      int val = inclusive[idx] + block_prefix;
      out_data[idx] = val - data[idx];
      if (idx == n - 1) out_data[n] = val;
    }
  }
}

