func run_scan():
	var rd = RenderingServer.create_local_rendering_device()
	var shader_file = load("res://scan.glsl")
	var shader_spirv = shader_file.get_spirv()
	var shader = rd.shader_create_from_spirv(shader_spirv)

	var f = FileAccess.open("res://data/input.txt", FileAccess.READ)
	var n = f.get_line().to_int()
	var input = PackedInt32Array()
	while f.get_position() < f.get_length():
		for x in f.get_line().split():
			if x.strip():
				input.append(x.strip().to_int())
	f.close()
	assert(input.size() == n)

	var input_buf = rd.storage_buffer_create(input.size() * 4, input.to_byte_array())
	var inclusive_buf = rd.storage_buffer_create(input.size() * 4, PackedByteArray())
	var block_count = (n + 255) / 256
	var block_sums_buf = rd.storage_buffer_create(block_count * 4, PackedByteArray())
	var out_buf = rd.storage_buffer_create((n + 1) * 4, PackedByteArray())

	var uniform_set = rd.uniform_set_create(
		[
			rd.uniform_create(RenderingDevice.UNIFORM_TYPE_STORAGE_BUFFER, 0, [input_buf]),
			rd.uniform_create(RenderingDevice.UNIFORM_TYPE_STORAGE_BUFFER, 1, [inclusive_buf]),
			rd.uniform_create(RenderingDevice.UNIFORM_TYPE_STORAGE_BUFFER, 2, [block_sums_buf]),
			rd.uniform_create(RenderingDevice.UNIFORM_TYPE_STORAGE_BUFFER, 3, [out_buf])
		],
		shader, 0
	)
	var pipeline = rd.compute_pipeline_create(shader)

	for pass in range(3):
		var dispatch_count = 1
		match pass:
			0: dispatch_count = block_count
			1: dispatch_count = 1
			2: dispatch_count = block_count
		var compute_list = rd.compute_list_begin()
		rd.compute_list_bind_compute_pipeline(compute_list, pipeline)
		rd.compute_list_bind_uniform_set(compute_list, uniform_set, 0)
		var push_const = PackedInt32Array([n, pass]).to_byte_array()
		rd.compute_list_set_push_constant(compute_list, shader, push_const)
		rd.compute_list_dispatch(compute_list, dispatch_count, 1, 1)
		rd.compute_list_end()
		rd.submit()
		rd.sync()

	var out_data = rd.buffer_get_data(out_buf).to_int32_array()
	var prefix_sum = []
	for i in range(n):
		prefix_sum.append(out_data[i])
	var total = out_data[n]

	var res = {
		"count": n,
		"total": total,
		"prefix_sum": prefix_sum
	}

	DirAccess.make_dir_recursive_absolute("res://output")
	var out_f = FileAccess.open("res://output/result.json", FileAccess.WRITE)
	out_f.store_string(JSON.stringify(res, "\t"))
	out_f.close()

	rd.free_rid(pipeline)
	rd.free_rid(uniform_set)
	rd.free_rid(out_buf)
	rd.free_rid(block_sums_buf)
	rd.free_rid(inclusive_buf)
	rd.free_rid(input_buf)
	rd.free_rid(shader)
	rd.free()
	get_tree().quit()

